mapper.delete:
delete from IBMMQ_LISTENER_DATA
where monitor_id = #{monitorId}
  and captureTime < #{captureTime}

mapper.select:
select *
from (
         select *
         from IBMMQ_LISTENER_DATA
         where monitor_id = #{monitorId}
         order by captureTime desc
     ) t
where rownum = 1

select *
from (
         select *
         from IBMMQ_LISTENER_DATA
         where monitor_id = #{monitorId}
         order by captureTime desc
     ) t
where rownum <= 50
